#include <iostream>
#include <vector>
using namespace std;

// Generate all subsets of {1, 2, 3}
void subsets(vector<int>& nums, int idx, vector<int>& current) {
    if (idx == nums.size()) {
        cout << "{ ";
        for (int x : current) cout << x << " ";
        cout << "}" << endl;
        return;
    }
    // Include nums[idx]
    current.push_back(nums[idx]);
    subsets(nums, idx + 1, current);
    // Exclude nums[idx] (backtrack)
    current.pop_back();
    subsets(nums, idx + 1, current);
}

// Generate all permutations
void permutations(vector<int>& nums, int idx) {
    if (idx == nums.size()) {
        for (int x : nums) cout << x << " ";
        cout << endl;
        return;
    }
    for (int i = idx; i < nums.size(); i++) {
        swap(nums[idx], nums[i]);
        permutations(nums, idx + 1);
        swap(nums[idx], nums[i]);  // backtrack
    }
}

int main() {
    vector<int> nums = {1, 2, 3};
    vector<int> current;
    cout << "Subsets:" << endl;
    subsets(nums, 0, current);
    cout << "\nPermutations:" << endl;
    permutations(nums, 0);
    return 0;
}

