import java.util.*;

public class Main {
    static void subsets(int[] nums, int idx, List<Integer> current, List<List<Integer>> result) {
        if (idx == nums.length) {
            result.add(new ArrayList<>(current));
            return;
        }
        current.add(nums[idx]);
        subsets(nums, idx + 1, current, result);
        current.remove(current.size() - 1);
        subsets(nums, idx + 1, current, result);
    }

    static void permutations(int[] nums, int idx) {
        if (idx == nums.length) {
            System.out.println(Arrays.toString(nums));
            return;
        }
        for (int i = idx; i < nums.length; i++) {
            int tmp = nums[idx]; nums[idx] = nums[i]; nums[i] = tmp;
            permutations(nums, idx + 1);
            tmp = nums[idx]; nums[idx] = nums[i]; nums[i] = tmp;
        }
    }

    public static void main(String[] args) {
        int[] nums = {1, 2, 3};
        List<List<Integer>> result = new ArrayList<>();
        subsets(nums, 0, new ArrayList<>(), result);
        System.out.println("Subsets: " + result);
        System.out.println("Permutations:");
        permutations(nums, 0);
    }
}

