// Generate all subsets
function subsets(nums, idx = 0, current = [], result = []) {
    if (idx === nums.length) {
        result.push([...current]);
        return result;
    }
    current.push(nums[idx]);
    subsets(nums, idx + 1, current, result);
    current.pop(); // backtrack
    subsets(nums, idx + 1, current, result);
    return result;
}

// Generate all permutations
function permutations(nums, idx = 0, result = []) {
    if (idx === nums.length) {
        result.push([...nums]);
        return result;
    }
    for (let i = idx; i < nums.length; i++) {
        [nums[idx], nums[i]] = [nums[i], nums[idx]];
        permutations(nums, idx + 1, result);
        [nums[idx], nums[i]] = [nums[i], nums[idx]]; // backtrack
    }
    return result;
}

console.log("Subsets:", subsets([1, 2, 3]));
console.log("Permutations:", permutations([1, 2, 3]));

