#include <stdio.h>

void printArr(int arr[], int n) {
    printf("{ ");
    for (int i = 0; i < n; i++) printf("%d ", arr[i]);
    printf("}\n");
}

// Generate all subsets
void subsets(int nums[], int n, int idx, int current[], int cSize) {
    if (idx == n) {
        printArr(current, cSize);
        return;
    }
    current[cSize] = nums[idx];
    subsets(nums, n, idx + 1, current, cSize + 1);
    subsets(nums, n, idx + 1, current, cSize);
}

void swap(int *a, int *b) { int t = *a; *a = *b; *b = t; }

void permutations(int nums[], int n, int idx) {
    if (idx == n) {
        for (int i = 0; i < n; i++) printf("%d ", nums[i]);
        printf("\n");
        return;
    }
    for (int i = idx; i < n; i++) {
        swap(&nums[idx], &nums[i]);
        permutations(nums, n, idx + 1);
        swap(&nums[idx], &nums[i]);
    }
}

int main() {
    int nums[] = {1, 2, 3};
    int current[3];
    printf("Subsets:\n");
    subsets(nums, 3, 0, current, 0);
    printf("\nPermutations:\n");
    permutations(nums, 3, 0);
    return 0;
}

