def is_safe(board, row, col, n):
    # Check column above
    for i in range(row):
        if board[i][col] == 'Q':
            return False
    # Check upper-left diagonal
    i, j = row - 1, col - 1
    while i >= 0 and j >= 0:
        if board[i][j] == 'Q':
            return False
        i -= 1; j -= 1
    # Check upper-right diagonal
    i, j = row - 1, col + 1
    while i >= 0 and j < n:
        if board[i][j] == 'Q':
            return False
        i -= 1; j += 1
    return True

def solve(board, row, n, results):
    if row == n:
        results.append([''.join(r) for r in board])
        return
    for col in range(n):
        if is_safe(board, row, col, n):
            board[row][col] = 'Q'
            solve(board, row + 1, n, results)
            board[row][col] = '.'  # backtrack

